import os
import urllib
import mimetypes
import logging
import re

log = logging.getLogger(__name__)
log.setLevel(logging.DEBUG)

map = mimetypes.MimeTypes()

regex = re.compile('^([^/]+/[^/]+)$')

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            mime = map.guess_type(urllib.pathname2url(self.path))[0]

            if (not mime) or regex.match(mime):
                ext = os.path.splitext(path)

                if ext[1]:
                    mime = map.guess_type(urllib.pathname2url(ext[1]))[0]

            self.type = mime

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

