from chainer.testing import backend as backend_testing
from chainer.testing import condition


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_backward(self, x_data, y_data):
        x = backend.get_device_from_array(x_data).assert_device()
        self.assertEqual(x.device.id,
                         backend.get_device_from_array(y_data).device.id)

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


@backend_testing.inputypes(
    types={'x': (np.ndarray, cuda.cupy.ndarray)},
)
@backend_testing.exec_options(options={'chainerx': True})
class TestCopy(unittest.TestCase):

    def check_forward(self, x_data):
        xp = backend.get_device_from_array(x_data).xp
        x = chainer.Variable(xp.asarray(x_data))
        if x_data.dtype == np.float16:
            with tests.assert_warns(details='Not implemented yet'):
                y = copy(x, 'host')
        else:
            y = copy(x, 'host')

        self.assertEqual(x_data.dtype, y.data.dtype)
        np.testing.assert_array_equal(x_data, y.data)

    @condition.retry(3)
    def test_forward(self):
        self.check_forward(self.x)

    def check_backward(self, x_data):
        x = chainer.Variable(x_data)
        with tests.assert_warns(
                DetachCopyWarning, details='Not implemented yet'):
            y = copy(x, 'host')
        y.backward()

        self.assertEqual(x.device.id, y.device.id)

    @condition.retry(3)
    @tests.for_types_including({'x': np.float16})
    def test_backward(self):
        self.check_backward(self.x)


testing.run_module(__name__, __file__)

